#[derive(Debug, Clone, PartialEq)]
struct DType {
    kind: char, // 'b', 'i', 'u', 'f', 'c', 'O'
    precedence: u32,
}

fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Assume types is non-empty
    types.into_iter().max_by_key(|dtype| dtype.precedence).unwrap()
}

fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let max_array = array_types.iter().max_by_key(|dtype| dtype.precedence);
    let max_scalar = scalar_types.iter().max_by_key(|dtype| dtype.precedence);

    match (max_array, max_scalar) {
        (Some(array_dtype), Some(scalar_dtype)) => {
            if array_dtype.kind == scalar_dtype.kind {
                Some(array_dtype.clone())
            } else {
                Some(scalar_dtype.clone())
            }
        }
        (Some(array_dtype), None) => Some(array_dtype.clone()),
        (None, Some(scalar_dtype)) => Some(scalar_dtype.clone()),
        (None, None) => None, // This case should not happen as per problem statement
    }
}

// Example usage
fn main() {
    let array_types = vec![
        DType { kind: 'i', precedence: 3 },
        DType { kind: 'f', precedence: 9 },
    ];
    let scalar_types = vec![
        DType { kind: 'i', precedence: 2 },
        DType { kind: 'b', precedence: 0 },
    ];

    let max_array_dtype = find_max_precedence_type(array_types.clone());
    println!("Max Array DType: {:?}", max_array_dtype);

    let common_dtype = find_common_type(array_types, scalar_types);
    println!("Common DType: {:?}", common_dtype);
}